alter table public.analises enable row level security;revoke all on table public.analises from anon;grant select,insert,update,delete on table public.analises to authenticated;grant select,insert,update,delete on table public.analises to service_role;
drop policy if exists "usuarios_leem_suas_analises" on public.analises;create policy "usuarios_leem_suas_analises" on public.analises for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "usuarios_criam_suas_analises" on public.analises;create policy "usuarios_criam_suas_analises" on public.analises for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists "usuarios_atualizam_suas_analises" on public.analises;create policy "usuarios_atualizam_suas_analises" on public.analises for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "usuarios_excluem_suas_analises" on public.analises;create policy "usuarios_excluem_suas_analises" on public.analises for delete to authenticated using((select auth.uid())=user_id);revoke execute on function public.set_analises_updated_at() from public,anon,authenticated;
